pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 initMinSum, uint256 newMinSum) internal {
        vm.assume(initMinSum != newMinSum);
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(initMinSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(newMinSum) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && c.MinSum() == initMinSum);
    }

    function testFuzz_run(uint256 initMinSum, uint256 newMinSum) public {
        _run(initMinSum, newMinSum);
    }

    receive() external payable {}
}
